function fitCamera(){const box=new THREE.Box3().setFromObject(state.modelRoot);if(box.isEmpty())return;const center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()),d=Math.max(size.x,size.y,size.z)*2.1;state.camera.position.set(center.x+d*.75,center.y-d,center.z+d*.72);state.controls.target.copy(center);state.camera.near=Math.max(.1,d/200);state.camera.far=d*15;state.camera.updateProjectionMatrix();state.controls.update();}

