function drawOverlay(canvas,path,tool){const ctx=canvas.getContext('2d'),rect=canvas.getBoundingClientRect();ctx.clearRect(0,0,rect.width,rect.height);if(!path.length)return;ctx.lineWidth=2;ctx.strokeStyle='#fb7185';ctx.fillStyle='rgba(96,165,250,.14)';ctx.setLineDash(tool==='pencil'?[]:[7,4]);ctx.beginPath();ctx.moveTo(path[0].x,path[0].y);path.slice(1).forEach(p=>ctx.lineTo(p.x,p.y));ctx.stroke();if(tool!=='pencil'&&path.length>2){ctx.closePath();ctx.fill();}}
