function loadDrawings(){if(!state.project)return;const host=$('drawingList'),entries=Object.entries(state.project.metadata.default_2d_views||{}).map(([view,uri])=>({view,artifact:state.project.artifacts[uri]})).filter(item=>item.artifact);host.innerHTML='';state.drawingProjectionRegions.clear();state.drawingProjectionPromises.clear();$('drawingCount').textContent=`${entries.length} ${entries.length===1?'rzut':'rzuty'} · wszystkie w jednym widoku`;state.activeDrawingView=entries[0]?.view||null;if(!entries.length){host.innerHTML='<div class="empty">Projekt nie zawiera rzutów 2D.</div>';return;}entries.forEach(({view,artifact},index)=>{const purpose=`viewer2d:${view}`,card=document.createElement('article');card.className=`drawing-card${index===0?' active':''}`;card.dataset.view=view;card.dataset.objectHighlight='none';card.innerHTML=`<header class="drawing-card-header"><div><h3>${esc(drawingViewLabel(view))}</h3><small>${esc(artifact.name)} · ${esc(artifact.uri)}</small></div><a class="button secondary" href="${esc(artifactUrl(artifact)||'/'+artifact.path)}" download>Pobierz SVG</a></header><div class="drawing-sheet"><img alt="Rzut ${esc(drawingViewLabel(view))}" /><canvas class="object-highlight-overlay" data-view="${esc(view)}" data-highlight-regions="0" aria-hidden="true"></canvas><canvas class="selection-overlay drawing-canvas" data-view="${esc(view)}" aria-label="Zaznaczenie na rzucie ${esc(drawingViewLabel(view))}"></canvas></div>`;host.appendChild(card);const image=card.querySelector('img'),canvas=card.querySelector('.drawing-canvas'),objectCanvas=card.querySelector('.object-highlight-overlay');bindDrawingCanvas(canvas);state.drawingProjectionPromises.set(view,loadDrawingProjectionRegions(view,artifact));image.onload=()=>{if(!state.artifactUses.some(item=>item.uri===artifact.uri&&item.purpose===purpose))state.artifactUses.push({uri:artifact.uri,path:artifact.path,purpose,status:'visible'});if(!state.visibleArtifactUris.includes(artifact.uri))state.visibleArtifactUris.push(artifact.uri);resizeCanvas(canvas);resizeCanvas(objectCanvas);renderObjectHighlight2d(view,objectCanvas);reportUiContext('viewer2d.artifact.loaded');};image.onerror=()=>{const error=Object.assign(new Error(`Nie udało się wczytać rysunku ${artifact.name}`),{code:'UI_ARTIFACT_LOAD_FAILED'});state.artifactUses.push({uri:artifact.uri,path:artifact.path,purpose,status:'failed',error_code:error.code});reportUiContext('viewer2d.artifact.failed',error);banner(error.message,'error');};image.src=artifactUrl(artifact)||'/'+artifact.path;});}
async function create2dSelection(path,tool,view,canvas){await state.drawingProjectionPromises.get(view);const inferred=inferDrawingProjection(path,view,canvas),target=inferred?.objectUri||state.selectedObjectUri;if(!target){drawOverlay(canvas,[],'pencil');const error=Object.assign(new Error('Nie można ustalić obiektu dla tego obszaru; wybierz go w drzewie'),{code:'UI_SELECTION_TARGET_REQUIRED'});banner(error.message,'error');reportUiContext('selection.rejected',error);return;}state.selection=makeSelection('2d',tool,path,[],[target]);const artifactUri=state.project.metadata.default_2d_views?.[view];state.selection.source_artifact_uri=artifactUri||null;if(inferred?.objectUri===target)state.selection.projection_entity_ids=[inferred.entityId];state.selection.notes=`drawing_view=${view}${inferred?`;projection_entity=${inferred.entityId}`:''}`;if(state.selectedObjectUri!==target)selectObject(target,'object.inferred');else updateSelectionSummary();reportUiContext('selection.created');}

async function saveAnnotation(){
  if(!state.selection){banner('Brak zaznaczenia','error');return;}
  const text=$('annotationText').value.trim();
  if(!text){banner('Wpisz uwagę','error');return;}
  const button=$('saveAnnotation'),selection=structuredClone(state.selection);button.disabled=true;
  try{const annotation=await api(`/api/v1/projects/${state.projectId}/annotations`,jbody({text,selection}));$('annotationText').value='';$('changePrompt').value=text;reportUiContext('annotation.execution.requested',null,`annotation=${shortUri(annotation.uri)};text_length=${text.length}`);await loadChangeHistory();await planChange({promptOverride:text,selectionOverride:selection,autoApply:true,annotationUri:annotation.uri});}
  catch(error){banner(error.message,'error');reportUiContext('annotation.execution.failed',error);}
  finally{button.disabled=false;}
}
async function planChange({promptOverride=null,selectionOverride=null,autoApply=false,annotationUri=null}={}){
  const selectionSource=selectionOverride||state.selection;
  if(!selectionSource){banner('Brak zaznaczenia','error');return;}
  const prompt=(promptOverride??$('changePrompt').value).trim();
  if(!prompt){banner('Wpisz opis zmiany','error');return;}
  const selection=structuredClone(selectionSource),projectId=state.projectId;
  state.plan=null;state.planApplyableCount=0;$('applyButton').disabled=true;$('applyButton').textContent='Oczekiwanie na plan…';$('applyStatus').className='apply-status hidden';$('planButton').disabled=true;
  setLocalTask('planning',{prompt,targetUris:selection.target_object_uris});
  startPlannerProgress(selection);
  try{
    const mapping=await api(`/api/v1/projects/${projectId}/selections/resolve`,jbody(selection));
    const result=await api(`/api/v1/projects/${projectId}/change-plans`,jbody({prompt,selection}));
    if(state.projectId!==projectId)throw Object.assign(new Error('W trakcie planowania zmieniono projekt. Plan zapisano, ale nie pokazano go w innym kontekście.'),{code:'UI_PLAN_CONTEXT_CHANGED'});
    state.selectionMap=mapping;state.plan=result.plan;
    const selectionChanged=state.selection?.uri!==selection.uri;
    $('plannerMode').textContent=`selection=${mapping.status}; ${result.mode}: ${result.message}${selectionChanged?' Plan dotyczy zaznaczenia z chwili wysłania.':''}`;
    renderPlan(result.plan);
    const blockers=(mapping.diagnostics||[]).filter(x=>x.severity==='blocking').length;
    finishPlannerProgress('success',result);
    banner(blockers?'Plan zapisany, ale mapowanie zawiera blokery — sprawdź pytania.':'Plan gotowy — poniżej sprawdź, czy zawiera zmianę możliwą do zastosowania.',blockers?'error':'success');
    if(autoApply&&state.planApplyableCount)await applyPlan({annotationUri,automatic:true});
    else if(autoApply){setLocalTask(null);const status=$('applyStatus');status.className='apply-status';status.textContent='Uwaga została zaplanowana, ale wymaga doprecyzowania lub CAD workera. Pozostaje otwarta w historii i kolejce zmian.';reportUiContext('annotation.execution.deferred',null,`annotation=${shortUri(annotationUri)};plan=${result.plan.plan_id};operations=${result.plan.operations.map(op=>op.kind).join(',')}`);await Promise.all([loadChangeQueue(),loadChangeHistory()]);}
    else{setLocalTask(null);await Promise.all([loadChangeQueue(),loadChangeHistory()]);}
  }catch(error){setLocalTask(null);finishPlannerProgress('error',null,error);banner(error.message,'error');await loadChangeQueue();}
  finally{$('planButton').disabled=false;}
}
function renderPlan(plan){
  const operations=plan.operations||[],applyable=operations.filter(op=>op.kind==='set_parameter'),deferred=operations.filter(op=>op.kind!=='set_parameter');
  state.planApplyableCount=applyable.length;
  const ops=operations.map(op=>`<div class="plan-op"><b>${esc(op.kind)}</b><code>${esc(op.target_uri)}</code><div>${esc(op.rationale)}</div><pre>${esc(JSON.stringify(op.arguments,null,2))}</pre></div>`).join('');
  const outcome=applyable.length
    ?`<div class="plan-impact info"><b>Do zapisania: ${applyable.length} ${applyable.length===1?'parametr':'parametry'}.</b> Zapis zaktualizuje dane projektu, ale nie zmieni widocznych STL/SVG, dopóki CAD worker nie zregeneruje artefaktów. Odświeżenie samej strony nie przebudowuje bryły.${deferred.length?` ${deferred.length} operacji pozostanie odroczonych.`:''}</div>`
    :`<div class="plan-impact warning"><b>Ten plan nie zmieni bryły.</b> Nie zawiera bezpiecznej zmiany parametru; operacje ${esc(deferred.map(op=>op.kind).join(', ')||'brak')} są tylko zapisane lub odroczone do CAD workera. Odświeżenie niczego nie zmieni. Doprecyzuj nazwę wymiaru lub konkretną operację.</div>`;
  $('planContent').className='plan-content';
  $('planContent').innerHTML=`<div class="kv"><span>plan</span><span>${esc(plan.plan_id)}</span></div>${outcome}${ops}${plan.unresolved_questions?.length?`<h3>Pytania</h3><ul>${plan.unresolved_questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul>`:''}`;
  $('applyButton').disabled=!applyable.length;
  $('applyButton').textContent=applyable.length?`Zapisz ${applyable.length} ${applyable.length===1?'bezpieczną zmianę parametru':'bezpieczne zmiany parametrów'}`:'Brak zmian możliwych do zastosowania';
}
async function applyPlan({annotationUri=null,automatic=false}={}){
  if(!state.plan||!state.planApplyableCount){const message='Ten plan nie zawiera zmiany możliwej do zastosowania bez CAD workera.';$('applyStatus').className='apply-status error';$('applyStatus').textContent=message;banner(message,'error');return;}
  setLocalTask('applying',{planId:state.plan.plan_id,prompt:state.plan.prompt,targetUris:state.plan.selected_scope_uris});
  const projectId=state.projectId,planId=state.plan.plan_id,button=$('applyButton'),status=$('applyStatus');button.disabled=true;status.className='apply-status';status.textContent='Zapisywanie bezpiecznych zmian parametrów…';reportUiContext('plan.apply.requested',null,`plan=${planId};applyable=${state.planApplyableCount}`);
  try{const response=await api(`/api/v1/projects/${projectId}/change-plans/${planId}/apply`,jbody({annotation_uri:annotationUri})),patches=response.result.parameter_patches.length,deferred=response.result.deferred_operations.length;status.className='apply-status success';status.textContent=`${automatic?'Uwaga wykonana automatycznie. ':''}Zapisano ${patches} ${patches===1?'zmianę parametru':'zmiany parametrów'}; ${deferred} operacji odroczono. Możesz cofnąć ten zapis w historii. Widoczne STL/SVG pozostaną bez zmian do czasu regeneracji przez CAD worker.`;reportUiContext('plan.apply.completed',null,`plan=${planId};patches=${patches};deferred=${deferred};automatic=${automatic}`);banner(`Zapisano ${patches} bezpiecznych zmian parametrów.`);setLocalTask(null);await refreshSnapshot(false);await Promise.all([loadChangeQueue(),loadChangeHistory()]);return true;}catch(error){setLocalTask(null);status.className='apply-status error';status.textContent=error.message;button.disabled=false;reportUiContext('plan.apply.failed',error,`plan=${planId};error=${error.code||'ERROR'}`);banner(error.message,'error');await loadChangeQueue();return false;}
}

function renderChangeQueue(){const host=$('changeQueue');if(!host)return;const tasks=effectiveQueueTasks();$('changeQueueCount').textContent=String(tasks.length);host.className=tasks.length?'change-queue':'change-queue empty';host.innerHTML=tasks.map(task=>{const meta=TASK_META[task.status]||{label:task.status,progress:0},targets=(task.target_uris||[]).map(shortUri).join(', '),question=task.unresolved_questions?.[0],details=question?`Bloker: ${question}`:`Operacje: ${(task.operation_kinds||[]).join(', ')||'ustalanie'}`,persisted=!String(task.task_id).startsWith('local:');return`<article class="queue-task" data-task-id="${esc(task.task_id)}" data-status="${esc(task.status)}"><header><b>${esc(meta.label)}</b><span class="history-status ${task.status==='ready'?'done':'queued'}">${esc(meta.short||task.status)}</span></header><div>${esc(task.prompt||'Przetwarzanie zmiany')}</div><small>${esc(targets||'brak celu')} · ${esc(details)}</small><div class="queue-progress"><span style="width:${Number(meta.progress||0)}%"></span></div>${persisted?`<button class="button queue-open" type="button" data-open-plan="${esc(task.plan_id)}">Pokaż plan i obiekt</button>`:''}</article>`;}).join('')||'Brak aktywnych zadań.';host.querySelectorAll('[data-open-plan]').forEach(button=>button.addEventListener('click',()=>openQueueTask(button.dataset.openPlan)));}
function openQueueTask(planId){const plan=state.project?.change_plans?.[planId];if(!plan){banner('Plan nie jest już dostępny w bieżącej rewizji','error');return;}state.plan=plan;$('changePrompt').value=plan.prompt;renderPlan(plan);const target=plan.selected_scope_uris?.[0];if(target&&state.project.objects[target])selectObject(target,'queue.task.opened');$('planContent').scrollIntoView({behavior:'smooth',block:'nearest'});reportUiContext('queue.task.opened',null,`plan=${planId};status=${state.changeQueue.find(task=>task.plan_id===planId)?.status||'unknown'}`);}
async function loadChangeQueue(){if(!state.projectId||!$('changeQueue'))return;try{const payload=await api(`/api/v1/projects/${state.projectId}/change-queue`);state.changeQueue=payload.tasks||[];renderTree();renderChangeQueue();}catch(error){const host=$('changeQueue');host.className='change-queue empty';host.textContent=`Nie udało się pobrać kolejki: ${error.message}`;}}
function changeHistoryContent(entry){const data=entry.data||{};if(entry.event_type==='AnnotationCreated'){const item=data.annotation||{};return{title:'Uwaga do wykonania',summary:item.text||'',status:item.status==='resolved'?'wykonana':'otwarta',statusClass:item.status==='resolved'?'done':'queued'};}if(entry.event_type==='AnnotationStatusChanged')return{title:'Status uwagi',summary:`${shortUri(data.annotation_uri||'')} → ${data.status}`,status:data.status,statusClass:data.status==='resolved'?'done':'queued'};if(entry.event_type==='ChangePlanCreated'){const plan=data.plan||{},kinds=(plan.operations||[]).map(op=>op.kind).join(', ');return{title:'Plan zmiany',summary:`${plan.prompt||''}${kinds?` · ${kinds}`:''}`,status:'zaplanowana',statusClass:'queued'};}if(entry.event_type==='ChangeApplied'){const patches=data.parameter_patches?.length||0,deferred=data.deferred_operations?.length||0;return{title:'Zastosowana zmiana',summary:`${patches} parametrów zapisano · ${deferred} operacji odroczono`,status:entry.reverted?'cofnięta':'wykonana',statusClass:entry.reverted?'undone':'done'};}if(entry.event_type==='ChangeReverted')return{title:'Cofnięcie zmiany',summary:`Przywrócono ${data.parameter_patches?.length||0} parametrów · zdarzenie ${data.reverts_event_id||''}`,status:'cofnięta',statusClass:'undone'};return{title:entry.event_type,summary:'',status:'zapisana',statusClass:''};}
async function loadChangeHistory(){if(!state.projectId||!$('changeHistory'))return;const host=$('changeHistory');try{const entries=await api(`/api/v1/projects/${state.projectId}/change-history?limit=100`);host.className='change-history';host.innerHTML=entries.map(entry=>{const content=changeHistoryContent(entry),when=new Date(entry.occurred_at).toLocaleString('pl-PL');return`<article class="change-history-item"><header><b>${esc(content.title)}</b><span class="history-status ${esc(content.statusClass)}">${esc(content.status)}</span></header><small>${esc(when)} · v${entry.stream_version} · ${esc(entry.actor)}</small><div>${esc(content.summary)}</div><code>${esc(entry.event_id)}</code>${entry.undo_available?`<button class="button undo-change" type="button" data-undo-event="${esc(entry.event_id)}">Cofnij tę zmianę</button>`:''}</article>`;}).join('')||'<div class="empty">Brak zapisanych zmian.</div>';host.querySelectorAll('[data-undo-event]').forEach(button=>{const entry=entries.find(item=>item.event_id===button.dataset.undoEvent),targets=(entry?.data?.parameter_patches||[]).map(patch=>patch.object_uri);button.addEventListener('click',()=>undoChange(button.dataset.undoEvent,button,targets));});}catch(error){host.className='change-history empty';host.textContent=`Nie udało się pobrać historii: ${error.message}`;}}
async function undoChange(eventId,button,targetUris=[]){button.disabled=true;setLocalTask('undoing',{planId:eventId,prompt:'Cofanie ostatniej zmiany',targetUris});reportUiContext('change.undo.requested',null,`event=${eventId}`);try{const response=await api(`/api/v1/projects/${state.projectId}/change-history/${encodeURIComponent(eventId)}/undo`,{method:'POST'});const restored=response.result.parameter_patches.length;setLocalTask(null);await refreshSnapshot(false);await Promise.all([loadChangeQueue(),loadChangeHistory()]);reportUiContext('change.undo.completed',null,`event=${eventId};restored=${restored}`);banner(`Cofnięto zmianę i przywrócono ${restored} parametrów.`);}catch(error){setLocalTask(null);button.disabled=false;await loadChangeQueue();reportUiContext('change.undo.failed',error,`event=${eventId};error=${error.code||'ERROR'}`);banner(error.message,'error');}}

function renderSpec(){const p=state.project;const objects=Object.values(p.objects);const yes=v=>v?'✓':'—';const rows=objects.map(n=>`<tr><td>${esc(n.name)}</td><td>${esc(n.kind)}</td><td>${esc(n.manufacturing?.make_buy)}</td><td>${esc(n.manufacturing?.process)}</td><td>${yes(n.inclusion?.print_job)}</td><td>${yes(n.inclusion?.cnc_job)}</td><td>${yes(n.inclusion?.purchase_order)}</td><td>${yes(n.inclusion?.pcb_fabrication)}</td><td>${yes(n.inclusion?.software_release)}</td><td>${yes(n.inclusion?.reference_only)}</td></tr>`).join('');const features=objects.flatMap(n=>(n.features||[]).map(f=>`<tr><td>${esc(n.name)}</td><td>${esc(f.name)}</td><td>${esc(f.feature_type)}</td><td>${esc(Object.entries(f.parameters||{}).map(([k,v])=>`${k}=${v.value}${v.unit||''}`).join(', '))}</td><td>${esc((f.semantic_faces||[]).map(shortUri).join(', '))}</td></tr>`)).join('');const artifacts=Object.values(p.artifacts).map(a=>{const key=a.uri.split('/artifact/')[1];const url=key?`/api/v1/projects/${state.projectId}/artifacts/${encodeURIComponent(key)}`:'#';return`<tr><td><a href="${url}">${esc(a.name)}</a></td><td>${esc(a.kind)}</td><td>${esc(shortUri(a.object_uri||''))}</td><td>${a.source?'source':'generated/reference'}</td><td>${esc(a.sha256?String(a.sha256).slice(0,12):'—')}</td></tr>`}).join('');$('specContent').innerHTML=`<section class="data-section"><h3>Obiekty / xBOM</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Obiekt</th><th>Typ</th><th>Make/Buy</th><th>Proces</th><th>3D print</th><th>CNC</th><th>Buy</th><th>PCB</th><th>Software</th><th>Reference</th></tr></thead><tbody>${rows}</tbody></table></div></section><section class="data-section"><h3>Cechy i wymiary</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Obiekt</th><th>Cecha</th><th>Typ</th><th>Parametry</th><th>Semantic faces</th></tr></thead><tbody>${features}</tbody></table></div></section><section class="data-section"><h3>Artefakty do pobrania</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Nazwa</th><th>Typ</th><th>Obiekt</th><th>Pochodzenie</th><th>SHA-256</th></tr></thead><tbody>${artifacts}</tbody></table></div></section>`;}
function renderLifecycle(){
  const p=state.project;
  const blueprints=Object.values(p.lifecycle_blueprints||{});
  const blueprintRows=blueprints.map(b=>`<tr><td>${esc(b.name||b.blueprint_id)}</td><td><code>${esc(b.blueprint_id)}</code></td><td>${esc(b.current_stage)}</td><td>${b.stages?.length||0}</td><td>${b.transitions?.length||0}</td><td>${b.tailored?'yes':'no'}</td></tr>`).join('');
  const history=[...(p.lifecycle_history||[])].sort((a,b)=>String(b.occurred_at||'').localeCompare(String(a.occurred_at||''))).map(h=>`<tr><td>${esc(h.occurred_at||'')}</td><td><code>${esc(h.blueprint_id)}</code></td><td>${esc(h.from_stage)} → ${esc(h.to_stage)}</td><td>${esc(h.status)}</td><td>${esc(h.approved_by||'—')}</td><td>${esc((h.unmet_criteria||[]).join('; ')||h.rationale||'—')}</td></tr>`).join('');
  const gates=(p.lifecycle_gates||[]).map(g=>`<tr><td>${esc(g.stage)}</td><td>${esc(g.status)}</td><td>${esc(g.exit_criteria.join('; '))}</td><td>${esc(g.approver_roles.join(', '))}</td></tr>`).join('');
  const failures=(p.failure_modes||[]).map(f=>{const r=f.severity*f.occurrence*f.detection;return`<tr><td>${esc(shortUri(f.target_uri))}</td><td>${esc(f.failure)}</td><td>${esc(f.effect)}</td><td class="${r>200?'rpn-high':r>100?'rpn-medium':'rpn-low'}">${r}</td></tr>`}).join('');
  const tests=Object.values(p.test_plans||{}).flatMap(plan=>(plan.cases||[]).map(t=>`<tr><td>${esc(plan.name)}</td><td>${esc(t.name)}</td><td>${esc(t.test_type)}</td><td>${esc(t.lifecycle_stage)}</td><td>${esc(t.status)}</td><td>${esc(t.execution_adapter)}</td></tr>`)).join('');
  const scenarios=(p.human_scenarios||[]).map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.actor)}</td><td>${esc(x.stage)}</td><td>${x.steps.length}</td></tr>`).join('');
  $('lifecycleContent').innerHTML=`
    <section class="data-section"><h3>Blueprinty lifecycle</h3><p class="hint">Aktualny etap projektu: <b>${esc(p.lifecycle_stage||'—')}</b></p><div class="table-wrap"><table class="data-table"><thead><tr><th>Nazwa</th><th>ID</th><th>Etap bieżący</th><th>Etapy</th><th>Przejścia</th><th>Tailored</th></tr></thead><tbody>${blueprintRows||'<tr><td colspan="6">Brak blueprintów zapisanych przez DSL.</td></tr>'}</tbody></table></div></section>
    <section class="data-section"><h3>Historia przejść</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Czas</th><th>Blueprint</th><th>Przejście</th><th>Status</th><th>Akceptacja</th><th>Evidence / blokery</th></tr></thead><tbody>${history||'<tr><td colspan="6">Brak przejść lifecycle.</td></tr>'}</tbody></table></div></section>
    <section class="data-section"><h3>Legacy gates / bramki projektu</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Etap</th><th>Status</th><th>Exit criteria</th><th>Role</th></tr></thead><tbody>${gates}</tbody></table></div></section>
    <section class="data-section"><h3>Plany testów</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Plan</th><th>Test</th><th>Typ</th><th>Etap</th><th>Status</th><th>Adapter</th></tr></thead><tbody>${tests}</tbody></table></div></section>
    <section class="data-section"><h3>Scenariusze obsługi przez człowieka</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Scenariusz</th><th>Aktor</th><th>Etap</th><th>Kroki</th></tr></thead><tbody>${scenarios}</tbody></table></div></section>
    <section class="data-section"><h3>FMEA / słabe punkty</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Cel</th><th>Uszkodzenie</th><th>Skutek</th><th>RPN</th></tr></thead><tbody>${failures}</tbody></table></div></section>`;
}
async function loadFeatureLenses(){if(!state.lensCatalog)state.lensCatalog=await api('/api/v1/feature-lenses?include_disabled=true');renderLensCatalog();}
function filteredLenses(){if(!state.lensCatalog)return[];const category=$('lensCategory')?.value||'';return state.lensCatalog.lenses.filter(l=>l.enabled&&(!category||l.category===category));}
function renderLensCatalog(){if(!state.lensCatalog||!$('lensCatalog'))return;const visible=filteredLenses();const sourceGap=state.lensCatalog.lenses.filter(l=>!l.enabled).length;const target=state.selectedObjectUri?shortUri(state.selectedObjectUri):'nie wybrano';$('lensCatalogSummary').textContent=`${state.lensCatalog.active_lens_count} aktywnych soczewek, ${sourceGap} jawna luka źródłowa; cel: ${target}.`;$('lensCatalog').innerHTML=visible.map(l=>`<div class="lens-row"><strong>${l.order}. ${esc(l.name)}</strong><small>${esc(l.category)} · ${esc(l.summary)}</small></div>`).join('')||'<div class="empty">Brak soczewek w tej kategorii.</div>';}
async function runFixation(){if(!state.selectedObjectUri){banner('Wybierz obiekt w drzewie przed przeglądem','error');return;}const button=$('fixationButton');button.disabled=true;$('fixationOutput').innerHTML='<div class="empty">Analiza soczewek…</div>';try{const lenses=filteredLenses().map(l=>l.id);const result=await api(`/api/v1/projects/${state.projectId}/design-fixation/scan`,jbody({target_uri:state.selectedObjectUri,challenge:$('fixationChallenge').value.trim(),lens_ids:lenses,max_alternatives:Number($('fixationMax').value||8),use_llm:$('fixationLlm').checked,record:true}));state.fixationReview=result.review;renderFixationReview(result.review,result.mode,result.message);banner(`Przegląd zapisany: ${result.review.alternatives.length} alternatyw`);await refreshSnapshot(false);}catch(error){$('fixationOutput').textContent=error.message;banner(error.message,'error')}finally{button.disabled=false;}}
function renderFixationHistory(){if(state.fixationReview)return;const reviews=Object.values(state.project?.design_fixation_reviews||{}).sort((a,b)=>String(a.created_at).localeCompare(String(b.created_at)));if(reviews.length)renderFixationReview(reviews.at(-1),'recorded','Ostatni zapisany przegląd.');else if($('fixationOutput'))$('fixationOutput').innerHTML='<div class="empty">Nie uruchomiono przeglądu.</div>';renderLensCatalog();}
function renderFixationReview(review,mode='recorded',message=''){if(!$('fixationOutput'))return;const pct=Math.round((review.coverage_ratio||0)*100);const observations=(review.observations||[]).map(o=>{const lens=state.lensCatalog?.lenses.find(l=>l.id===o.lens_id);return`<tr><td>${esc(lens?.name||o.lens_id)}</td><td class="status-${esc(o.status)}">${esc(o.status)}</td><td>${esc(o.note)}</td></tr>`}).join('');const ideas=(review.alternatives||[]).map(i=>`<article class="idea-card"><h4>${esc(i.title)}</h4><div class="lens-tags">${i.lens_ids.map(id=>`<span class="lens-tag">${esc(id)}</span>`).join('')}</div><p>${esc(i.summary)}</p>${i.proposed_changes?.length?`<b>Propozycje</b><ul>${i.proposed_changes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${i.risks?.length?`<b>Ryzyka</b><ul>${i.risks.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<div class="hint">źródło: ${esc(i.source)} · confidence ${Math.round((i.confidence||0)*100)}%</div></article>`).join('');$('fixationOutput').innerHTML=`<div class="coverage"><b>${pct}% pokrycia</b><div class="coverage-meter"><span style="width:${pct}%"></span></div><span>${review.observed_count}/${review.applicable_count}</span></div><p class="hint">${esc(mode)} · ${esc(message)} · ${esc(review.target_uri)}</p><h3>Alternatywy</h3>${ideas||'<div class="empty">Brak alternatyw.</div>'}<details><summary>Macierz obserwacji (${review.observations.length})</summary><div class="table-wrap"><table class="data-table observation-table"><thead><tr><th>Soczewka</th><th>Status</th><th>Uzasadnienie</th></tr></thead><tbody>${observations}</tbody></table></div></details>${review.warnings?.length?`<details><summary>Uwagi źródłowe</summary><ul>${review.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}`;}


function defaultTwinScript(){const target=state.selectedObjectUri||Object.keys(state.project?.objects||{}).find(uri=>uri.endsWith('/part/base'))||`poa://demo/${state.projectId||'demo-rpi5'}@main/part/base`;const revision=state.project?.revision||'main';return `TWINSCRIPT 1.0
NAME "${state.project?.name||'Product'} evolution"
NAMESPACE product
LABEL workflow=design-evolution

PROJECT ${state.projectId||'demo-rpi5'} REVISION ${revision}
FOCUS "${target}"

GOAL VERB improve OBJECT "selected product region" \\
  OUTCOME "better function, manufacturability and lifecycle evidence without assuming the current form is fixed"
PRESERVE "approved interfaces and safety constraints"
AVOID "changes outside the selected POA scope"
ASSUME "the current implementation is one candidate, not the goal itself"

METHODS goal_ladder,object_decomposition,bidirectional_graph,feature_lenses,adjacent_possible,brainswarm,assumption_reversal,mutation,recombination,experiment
SEED_VERBS improve,simplify,manufacture,inspect
LENSES parts,material,shape,size,connectivity_among_parts,spatial_relations_among_parts,force_characteristics,durability_characteristics,human_use,causal_relations,aesthetics
DIMENSIONS manufacturability,assemblability,serviceability,testability,reliability,reversibility,experiment_cost,adjacent_possible
LENS_OPTIONS SOURCE true EXTENSIONS true ASSUMPTIONS true MAX 96
RESOURCE_OPTIONS DESCENDANTS true FEATURES true PARAMETERS true MATERIALS true PROCESSES true ARTIFACTS true REQUIREMENTS true EVIDENCE true MAX 250
SEARCH UP 1 DOWN 2 SIDEWAYS 1 MAX 40 OPPOSITES true

EVOLVE POPULATION 12 GENERATIONS 3 OFFSPRING 2 MUTATION 0.8 CROSSOVER 0.3 SEED 17
OPERATOR reframe_goal WEIGHT 1.0
OPERATOR repurpose_feature WEIGHT 1.0
OPERATOR parameter_shift WEIGHT 0.8
OPERATOR make_reversible WEIGHT 0.8
OPERATOR adjacent_association WEIGHT 1.0
OPERATOR crossover WEIGHT 0.4
SELECT_TOP 5
MIN_SCORE 0.25

LIFECYCLE hardware-product START detailed_design TARGET verification APPROVAL true
GATE experiment CHECK "shortlisted concepts have recorded experiments" ROLE creator,admin BLOCKING true
VERIFY "build or simulate the shortlisted concept"
VERIFY "record evidence against preserved constraints"
REALIZE change_plan DRY_RUN true APPROVAL true MAX_PLANS 3
OUTPUT GRAPHS json,dot,mermaid REPORTS json,markdown,csv
PERSIST_ARTIFACTS true
INCLUDE_CHANGE_PLANS true
NOTE "Generated candidates are hypotheses and require verification."
END
`;}
function ensureDslTemplate(force=false){const editor=$('dslSource');if(!editor)return;if(force||!editor.value.trim())editor.value=defaultTwinScript();}
function dslDiagnosticsHtml(items=[]){return `<div class="dsl-diagnostics">${items.map(d=>`<div class="dsl-diagnostic ${esc(d.severity)}"><b>${esc(d.severity)} · ${esc(d.code)}</b><div>${esc(d.message)}</div>${d.path?`<small>${esc(d.path)}</small>`:''}</div>`).join('')||'<div class="hint">Brak diagnostyki.</div>'}</div>`;}
function renderDslCompilation(payload){state.dslPreview=payload;const out=$('dslOutput');if(!out)return;const run=payload.evolution_run;const selected=new Set(run?.selected_candidate_ids||[]);const candidates=(run?.candidates||[]).filter(c=>selected.has(c.candidate_id)).map(c=>`<article class="candidate-card"><h4>${esc(c.title)}</h4><div class="candidate-score">score ${Number(c.overall_score||0).toFixed(3)} · generation ${esc(c.generation)}</div><p>${esc(c.summary)}</p><div class="lens-tags">${(c.lens_ids||[]).slice(0,10).map(x=>`<span class="lens-tag">${esc(x)}</span>`).join('')}</div>${c.validation_steps?.length?`<details><summary>Walidacja</summary><ul>${c.validation_steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}</article>`).join('');const plans=(payload.change_plans||[]).map(p=>`<li><code>${esc(p.plan_id)}</code> — ${p.operations?.length||0} operacji, status ${esc(p.status)}</li>`).join('');const blueprint=payload.lifecycle_blueprint;out.className='';out.innerHTML=`<div class="dsl-summary"><b>${payload.valid?'Program poprawny':'Program zablokowany'}</b>${payload.execution?`<div class="hint">execution: ${esc(payload.execution.execution_id)} · ${esc(payload.execution.status)}</div>`:''}${run?`<div class="coverage"><b>${run.goal_variants.length} wariantów celu</b><span>${run.resources.length} zasobów · ${run.candidates.length} kandydatów · ${run.selected_candidate_ids.length} shortlist</span></div>`:''}${blueprint?`<p>Lifecycle: <code>${esc(blueprint.blueprint_id)}</code>, current ${esc(blueprint.current_stage)} → target ${esc(payload.document?.spec?.lifecycle?.target_stage||'configured stages')}</p>`:''}${plans?`<h3>Typed ChangePlans</h3><ul class="dsl-plan-list">${plans}</ul>`:''}${payload.artifact_keys?`<p class="hint">Artefakty: ${esc(Object.keys(payload.artifact_keys).join(', '))}</p>`:''}</div>${dslDiagnosticsHtml(payload.diagnostics||[])}${run?`<div class="dsl-summary"><h3>Shortlista ewolucji</h3>${candidates||'<div class="empty">Brak kandydatów spełniających próg.</div>'}</div>`:''}`;}
async function previewDsl(){const button=$('dslPreviewButton');button.disabled=true;$('dslOutput').innerHTML='<div class="empty">Kompilowanie grafu celu, zasobów i wariantów…</div>';try{const payload=await api(`/api/v1/projects/${state.projectId}/dsl/preview`,jbody({source:$('dslSource').value,source_format:$('dslFormat').value}));renderDslCompilation(payload);banner(payload.valid?'Podgląd ewolucji gotowy':'DSL wymaga korekty',payload.valid?'success':'error');}catch(error){$('dslOutput').textContent=error.message;banner(error.message,'error')}finally{button.disabled=false;}}
async function applyDsl(){if(!$('dslCommit').checked){banner('Zaznacz potwierdzenie zapisu zdarzeń','error');return;}const button=$('dslApplyButton');button.disabled=true;try{const payload=await api(`/api/v1/projects/${state.projectId}/dsl/apply`,jbody({source:$('dslSource').value,source_format:$('dslFormat').value,dry_run:false,generate_artifacts:true}));renderDslCompilation(payload);await refreshSnapshot(false);banner(`Zapisano ${payload.events?.length||0} zdarzeń i artefakty ewolucji`);}catch(error){banner(error.message,'error')}finally{$('dslCommit').checked=false;button.disabled=true;}}
function renderEvolutionHistory(){const host=$('evolutionHistory');if(!host||!state.project)return;const runs=Object.values(state.project.evolution_runs||{}).sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')));const executions=Object.values(state.project.dsl_executions||state.project.dsl_programs||{}).sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')));const blueprints=Object.values(state.project.lifecycle_blueprints||{});host.innerHTML=`<h3>Historia projektu</h3><div class="hint">${runs.length} runów · ${executions.length} wykonań DSL · ${blueprints.length} blueprintów lifecycle</div>${runs.slice(0,8).map(r=>`<div class="history-item"><b>${esc(r.program?.metadata?.name||r.run_id)}</b><div><code>${esc(r.run_id)}</code> · ${r.candidates?.length||0} kandydatów · ${r.selected_candidate_ids?.length||0} shortlist</div></div>`).join('')||'<div class="empty">Brak zapisanych runów.</div>'}`;}

async function runSimulation(type){const out=$('simulationOutput');out.textContent='Uruchamianie…';try{let result;if(type==='power')result=await api(`/api/v1/projects/${state.projectId}/simulations/power`,{method:'POST'});if(type==='thermal'){const rpi=Object.keys(state.project.objects).find(u=>u.includes('raspberry-pi-5'));const enclosure=Object.keys(state.project.objects).find(u=>u.endsWith('/assembly/enclosure'));result=await api(`/api/v1/projects/${state.projectId}/simulations/thermal`,jbody({power_by_uri_w:{[rpi]:10,[enclosure]:1.5},duration_s:600,sample_every_s:30}));}if(type==='human')result=await api(`/api/v1/projects/${state.projectId}/simulations/human`);if(type==='mechanical')result=await api(`/api/v1/projects/${state.projectId}/checks/mechanical`);out.textContent=JSON.stringify(result,null,2);}catch(error){out.textContent=error.message;}}
async function invite(){const email=$('inviteEmail').value.trim();if(!email){banner('Wpisz email','error');return;}try{const result=await api('/api/v1/access-requests',jbody({project_id:state.projectId,requested_email:email,requested_role:$('inviteRole').value,message:'Access requested from the project web UI.'}));$('inviteStatus').textContent=`Wysłano do decydenta: ${result.approver_email}`;banner('Wniosek o dostęp zapisany');}catch(error){banner(error.message,'error')}}

function bindActions(){$('projectSelect').addEventListener('change',async e=>{state.projectId=e.target.value;clearSelection();await loadProject()});$('downloadTabPdf').addEventListener('click',downloadActiveTabPdf);$('copyDslLogs').addEventListener('click',copyDslLogs);$('refreshButton').addEventListener('click',()=>refreshSnapshot());document.querySelectorAll('.tool[data-tool]').forEach(b=>{if(!b.classList.contains('tool2d'))b.addEventListener('click',()=>activateTool(b.dataset.tool,'3d'))});document.querySelectorAll('.tool2d').forEach(b=>b.addEventListener('click',()=>activateTool(b.dataset.tool,'2d')));$('clearSelection').addEventListener('click',clearSelection);$('clearSelection2d').addEventListener('click',clearSelection);$('fitCamera').addEventListener('click',fitCamera);$('xrayToggle').addEventListener('change',e=>state.meshes.forEach(m=>{m.material.opacity=e.target.checked?.45:1;m.material.depthWrite=!e.target.checked}));$('saveAnnotation').addEventListener('click',saveAnnotation);$('planButton').addEventListener('click',()=>planChange());$('applyButton').addEventListener('click',()=>applyPlan());$('refreshChangeHistory').addEventListener('click',()=>Promise.all([loadChangeQueue(),loadChangeHistory()]));$('powerButton').addEventListener('click',()=>runSimulation('power'));$('thermalButton').addEventListener('click',()=>runSimulation('thermal'));$('humanButton').addEventListener('click',()=>runSimulation('human'));$('mechanicalButton').addEventListener('click',()=>runSimulation('mechanical'));$('fixationButton').addEventListener('click',runFixation);$('lensCategory').addEventListener('change',renderLensCatalog);$('dslTemplateButton').addEventListener('click',()=>ensureDslTemplate(true));$('dslPreviewButton').addEventListener('click',previewDsl);$('dslCommit').addEventListener('change',e=>$('dslApplyButton').disabled=!e.target.checked);$('dslApplyButton').addEventListener('click',applyDsl);$('inviteButton').addEventListener('click',invite);}
init().catch(error=>{banner(`${error.message}${error.code?` (${error.code})`:''}`,'error');reportUiContext('application.init.failed',error);});
